import{_ as i,C as o,o as a,c as l,a2 as t,b as d,w as s,a as r,E as p,a3 as h}from"./chunks/framework.CZqXuAiL.js";const y=JSON.parse('{"title":"Quick Start","description":"Install Bandwidth Monitor for Pterodactyl in ten minutes — Blueprint the panel addon, pair one Wings node, set a speed cap, and watch tc enforce it.","frontmatter":{"title":"Quick Start","description":"Install Bandwidth Monitor for Pterodactyl in ten minutes — Blueprint the panel addon, pair one Wings node, set a speed cap, and watch tc enforce it."},"headers":[],"relativePath":"pterodactyl-bandwidth-monitor/getting-started/quick-start.md","filePath":"pterodactyl-bandwidth-monitor/getting-started/quick-start.md","lastUpdated":null}'),c={name:"pterodactyl-bandwidth-monitor/getting-started/quick-start.md"};function g(u,e,k,b,m,f){const n=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>This is the fastest path from zero to a live, enforced bandwidth limit: panel addon in, one node paired, one speed cap set. Total time is about <strong>ten minutes</strong> on a single machine that hosts both the panel and a Wings node (the same steps apply when they&#39;re separate).</p><p><strong>You&#39;ll need:</strong></p><ul><li>A Pterodactyl v1.12.x panel with Blueprint (<code>beta-2026-05</code>) installed and root shell access</li><li>A Wings node with Docker, <code>tc</code> (iproute2) and systemd</li><li>The <code>pterodactylbandwidth-v1.0.0.blueprint</code> archive and the <code>node-module/</code> directory</li></ul><h2 id="_1-install-the-panel-addon" tabindex="-1">1. Install the panel addon <a class="header-anchor" href="#_1-install-the-panel-addon" aria-label="Permalink to &quot;1. Install the panel addon&quot;">​</a></h2><p>Copy the Blueprint archive into your panel directory and install it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylbandwidth-v1.0.0.blueprint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl/</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylbandwidth-v1.0.0</span></span></code></pre></div><p>Blueprint runs the addon&#39;s installer: it copies the controllers, services, jobs and migrations into the panel, runs the migrations (creating the <code>bandwidth_*</code> tables), patches the server build configuration with bandwidth fields, and adds a <strong>Bandwidth</strong> section to the admin sidebar.</p><p>Open your panel&#39;s admin area — you should see <strong>Bandwidth</strong> in the sidebar with Dashboard, Nodes, Servers, Reports, Events and Settings.</p><h2 id="_2-copy-the-node-pairing-token" tabindex="-1">2. Copy the node pairing token <a class="header-anchor" href="#_2-copy-the-node-pairing-token" aria-label="Permalink to &quot;2. Copy the node pairing token&quot;">​</a></h2><p>Go to <strong>Admin → Bandwidth → Nodes</strong>. Every Pterodactyl node already has a row with a generated pairing token. Click <strong>view</strong> on your node&#39;s row and copy the 64-hex token.</p><div class="info custom-block"><p class="custom-block-title">TOKENS ARE PER NODE</p><p>Each node has its own token. If one leaks, hit <strong>reset</strong> on that row — the old token dies immediately and only that node needs re-pairing.</p></div><h2 id="_3-install-the-node-agent" tabindex="-1">3. Install the node agent <a class="header-anchor" href="#_3-install-the-node-agent" aria-label="Permalink to &quot;3. Install the node agent&quot;">​</a></h2><p>On the Wings node, as root, from the <code>node-module/</code> directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><p>The installer prompts (answers in <strong>bold</strong> below are examples):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[install] bandwidth-node installer</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Panel URL (e.g. https://panel.example.com): https://panel.example.com</span></span>
<span class="line"><span>Node token (64 hex characters, from the panel Nodes page): a1b2c3…(64 hex chars)</span></span>
<span class="line"><span>Listen address [0.0.0.0]:</span></span>
<span class="line"><span>Listen port [8480]:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[install] Panel URL:     https://panel.example.com</span></span>
<span class="line"><span>[install] Listen:        0.0.0.0:8480</span></span>
<span class="line"><span>[install] Go toolchain found — building from source</span></span>
<span class="line"><span>[install] binaries installed to /usr/local/bin</span></span>
<span class="line"><span>[install] wrote /etc/bandwidth-node/config.yaml and /etc/bandwidth-node/token (0600)</span></span>
<span class="line"><span>[install] systemd unit installed and started</span></span>
<span class="line"><span>[install] waiting for the agent to register with the panel (up to 90s)...</span></span>
<span class="line"><span>[install] SUCCESS — node registered with the panel.</span></span>
<span class="line"><span>[install] Agent API: http://0.0.0.0:8480/api/v1/health</span></span></code></pre></div><p>The installer validates both inputs (URL format, exactly 64 hex characters), writes the config and token files, installs the <code>bandwidth-node.service</code> systemd unit, and waits for the agent to confirm registration with the panel.</p><p>Back in the panel, the <strong>Nodes</strong> page now shows the node as <strong>online</strong>.</p><div class="warning custom-block"><p class="custom-block-title">USE HTTPS FOR THE PANEL URL</p><p>The bearer token and bandwidth data travel over this connection. The installer warns if you enter a plain <code>http://</code> URL — use <code>https://</code> in production.</p></div><p>If registration doesn&#39;t confirm, check the agent logs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bandwidth-node.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>The usual causes are a wrong panel URL, a wrong token, or the panel being unreachable from the node. The agent retries registration with backoff, so fixing the cause is enough — no reinstall needed.</p><h2 id="_4-set-a-speed-cap" tabindex="-1">4. Set a speed cap <a class="header-anchor" href="#_4-set-a-speed-cap" aria-label="Permalink to &quot;4. Set a speed cap&quot;">​</a></h2><p>Pick any running server on that node:</p><ol><li>Open <strong>Admin → Bandwidth → Servers</strong>.</li><li>Find the server and set <strong>RX speed</strong> and <strong>TX speed</strong> (Mbps). Try <code>10</code> for TX. Make sure <strong>enabled</strong> is on, and save.</li></ol><p>The panel pushes the new limits to the node (<code>PUT /limits</code>) — and on its next 60-second heartbeat the node also sees the bumped config version and re-pulls to be sure. The agent applies the cap with <code>tc</code>: an HTB class on the container&#39;s veth for TX (egress), an ingress qdisc with policing for RX.</p><h2 id="_5-watch-it-enforce" tabindex="-1">5. Watch it enforce <a class="header-anchor" href="#_5-watch-it-enforce" aria-label="Permalink to &quot;5. Watch it enforce&quot;">​</a></h2><p>On the node:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bandwidth-node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # live per-server counters and rates</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bandwidth-node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # daemon + panel sync status</span></span></code></pre></div><p>Generate traffic from the server (a download, a speed test, players joining). <code>bandwidth-node list</code> shows the server&#39;s <code>tx_rate_bps</code> pinned just under the cap — in our live verification a <strong>10 Mbps cap held a server at ~9.5 Mbps</strong>.</p><p>In the panel, the <strong>Dashboard</strong> chart picks the server up within a minute (the panel polls each online node for stats every 60 seconds), and the <strong>Events</strong> page records a <code>speed_applied</code> event.</p><div class="tip custom-block"><p class="custom-block-title">QUOTAS WORK THE SAME WAY</p><p>Set a small quota — e.g. a 1 GiB daily TX quota with exceed action <strong>throttle</strong> — and push traffic past it. The node throttles the server to the configured throttle speeds (default 5 Mbps) and logs <code>quota_exceeded</code> + <code>throttled</code> events to the panel. With action <strong>suspend</strong>, the server is actually suspended via the panel. Both were verified live.</p></div><h2 id="_6-set-your-fleet-defaults" tabindex="-1">6. Set your fleet defaults <a class="header-anchor" href="#_6-set-your-fleet-defaults" aria-label="Permalink to &quot;6. Set your fleet defaults&quot;">​</a></h2><p>Open <strong>Admin → Bandwidth → Settings</strong> and set the default speed caps, quotas and exceed action. These prefill the bandwidth fields on the server build configuration, so every <em>new</em> server is born with sane limits — per-server overrides stay on the <strong>Servers</strong> page.</p><hr><h2 id="the-60-second-mental-model" tabindex="-1">The 60-second mental model <a class="header-anchor" href="#the-60-second-mental-model" aria-label="Permalink to &quot;The 60-second mental model&quot;">​</a></h2>`,37)),(a(),d(h,null,{default:s(()=>[p(n,{id:"mermaid-128",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22blueprint%20-i%3Cbr%2F%3Epanel%20addon%22%5D%20--%3E%20B%5B%22Nodes%20page%3A%3Cbr%2F%3Ecopy%20token%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22install.sh%3Cbr%2F%3Eon%20the%20node%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Node%20online%3Cbr%2F%3Ein%20panel%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Set%20cap%20on%3Cbr%2F%3EServers%20page%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22tc%20enforces%3Cbr%2F%3Eon%20the%20node%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./../">Overview →</a></strong> — Architecture, full feature list, and the comparison with standalone Bandwidth Manager.</li><li>Set quotas with the <strong>suspend</strong> action for abusive tiers, and check <strong>Reports</strong> (CSV export included) for billing-ready usage data.</li><li><code>bandwidth-node --help</code> on the node for the full CLI (<code>limits</code>, <code>unthrottle</code>, <code>doctor</code>, <code>reapply</code>).</li></ul>',3))])}const w=i(c,[["render",g]]);export{y as __pageData,w as default};
